#!/usr/bin/env node
'use strict';
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process'),crypto=require('node:crypto');
const variants=[{"label":"Progress anterior","hash":"da5792b6296a0fe452085b041e0dda806e8706d5a95b6915afe01d71a6d5f694","files":["app/(tabs)/tracking/index.tsx","components/progress/ProgressDashboard.tsx","components/progress/ProgressSummary.tsx","docs/progress-clarity.md","tests/progress-clarity.cjs","tests/unified-progress.cjs"],"payload":""},{"label":"Base estable","hash":"3eaa45de1cb5b612095f30aa12af842b4863a9d38a524c03c481820a43d1dee0","files":["app/(tabs)/tracking/index.tsx","app/progress/connections.tsx","components/progress/JourneyDashboard.tsx","components/progress/ProgressDashboard.tsx","components/progress/ProgressSummary.tsx","docs/progress-clarity.md","hooks/useProgressHealth.ts","lib/progress-summary.ts","package.json","tests/progress-clarity.cjs","tests/unified-progress.cjs"],"payload":""}];
const git=(args,input)=>cp.spawnSync('git',args,{cwd:process.cwd(),encoding:'utf8',input,maxBuffer:16*1024*1024});
function fail(message){console.error(message);process.exit(1)}
const root=git(['rev-parse','--show-toplevel']);
if(root.status!==0)fail('Abrí Git Bash dentro de TreksorDevCompleto.');
process.chdir(root.stdout.trim());
const remote=git(['remote','get-url','origin']);
if(remote.status!==0||!/treksorapp-cmd\/TreksorApp(?:\.git)?\s*$/i.test(remote.stdout))fail('El repositorio no es TreksorApp. No se modificó nada.');
if(git(['ls-files','-u']).stdout.trim())fail('Hay un conflicto de Git pendiente. No se modificó nada.');
for(const variant of variants){
 variant.patch=Buffer.from(variant.payload,'base64').toString('utf8');
 if(crypto.createHash('sha256').update(variant.patch).digest('hex')!==variant.hash)fail('El parche está incompleto. No se modificó nada.');
 for(const file of variant.files){let current=process.cwd();for(const part of file.split('/')){current=path.join(current,part);if(fs.existsSync(current)&&fs.lstatSync(current).isSymbolicLink())fail('No se puede modificar un enlace: '+file)}}
}
if(variants.some(v=>git(['apply','--reverse','--check','--whitespace=nowarn','-'],v.patch).status===0)){
 console.log('PROGRESS MINIMAL YA INSTALADO. Reiniciá Expo y abrí Treksor Dev.');process.exit(0);
}
const variant=variants.find(v=>git(['apply','--check','--whitespace=nowarn','-'],v.patch).status===0);
if(!variant){
 for(const v of variants){console.error(v.label+':');console.error(git(['apply','--check','--whitespace=nowarn','-'],v.patch).stderr)}
 fail('Tu copia tiene cambios que se superponen. No se modificó ningún archivo. Conservá esta salida para adaptar el parche.');
}
if(!process.argv.includes('--apply')){console.log('COMPATIBLE: '+variant.label+' · '+variant.files.length+' archivos. No se escribió nada. Usá --apply para instalar con respaldo.');process.exit(0)}
const compiler=path.join(process.cwd(),'node_modules/typescript/bin/tsc');
if(!fs.existsSync(compiler))fail('Faltan las dependencias de esta copia. No se modificó nada.');
const original=new Map(variant.files.map(file=>[file,fs.existsSync(file)?fs.readFileSync(file):null]));
const backup=fs.mkdtempSync(path.join(path.dirname(process.cwd()),'Treksor-progress-minimal-backup-'));
for(const [file,bytes] of original){if(bytes!==null){const target=path.join(backup,file);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,bytes)}}
fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify({root:process.cwd(),revision:'progress-minimal-20261128',from:variant.label,files:variant.files.map(file=>({file,existed:original.get(file)!==null}))},null,2));
function restore(){for(const [file,bytes] of original){if(bytes===null)fs.rmSync(file,{force:true});else fs.writeFileSync(file,bytes)}}
if(git(['apply','--whitespace=nowarn','-'],variant.patch).status!==0){restore();fail('No se pudo aplicar. Se restauraron los archivos. Respaldo: '+backup)}
for(const args of [[compiler,'--noEmit','-p','tsconfig.mobile.json'],['tests/progress-clarity.cjs'],['tests/unified-progress.cjs']]){
 const result=cp.spawnSync(process.execPath,args,{cwd:process.cwd(),stdio:'inherit',timeout:180000});
 if(result.status!==0){restore();fail('La validación local falló. Se restauraron los archivos originales. Respaldo: '+backup)}
}
console.log('PROGRESS MINIMAL INSTALADO Y VALIDADO. Respaldo: '+backup);
console.log('Se conservaron tu rama, tus datos y los tamaños de la interfaz. Reiniciá Expo en esta carpeta.');
console.log('Vista principal: active days, Log activity y Recent activity.');
